CREATE FUNCTION public.validate_remittance_breakdown() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE subtotal numeric; BEGIN IF NEW.kind='remittance' THEN IF jsonb_typeof(NEW.breakdown)<>'object' THEN RAISE EXCEPTION 'A remittance breakdown is required'; END IF; SELECT COALESCE(sum(value::numeric),0) INTO subtotal FROM jsonb_each_text(NEW.breakdown); IF EXISTS(SELECT 1 FROM jsonb_each_text(NEW.breakdown) WHERE value::numeric<0) OR abs(subtotal-NEW.amount)>0.01 THEN RAISE EXCEPTION 'Remittance breakdown must match the total and contain no negative amounts'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER check_remittance_breakdown BEFORE INSERT OR UPDATE ON public.treasury_transactions FOR EACH ROW EXECUTE FUNCTION public.validate_remittance_breakdown();